[HttpPost("reset")]
public async Task<IActionResult> Reset(string email, string newPassword)
{
    var user = await db.Users.FirstAsync(u => u.Email == email);
    user.PasswordHash = _hasher.HashPassword(user, newPassword);
    await db.SaveChangesAsync();
    return Ok();
}
